/**
 * Capture a schema-shaped restaurant-arena-trace-v3 record from a running game.
 * Overlay callers import this helper directly.
 */
export function captureArenaTrace(
  game: ArenaTraceCaptureSource,
  options: TraceCaptureOptions,
): RestaurantArenaTraceV3 {
  if (
    options == null ||
    (options.runKind !== "live" && options.runKind !== "synthetic" && options.runKind !== "benchmark")
  ) {
    throw new Error("runKind is required and must be live, synthetic, or benchmark");
  }

  const recorded = options.events
    ? structuredClone(options.events)
    : structuredClone(game.getRecordedEvents());
  const extras = (options.additionalEvents ?? []).map((event) => {
    const cloned = structuredClone(event);
    cloned.round = roundForTick(cloned.tick);
    return cloned;
  });
  const events = extras.length === 0 ? recorded : [...recorded, ...extras].sort((left, right) => left.tick - right.tick);

  if (options.startTime !== undefined) {
    const base = Date.parse(options.startTime);
    if (!Number.isFinite(base)) throw new Error("startTime must be an ISO date-time string");
    for (const event of events) {
      event.timestamp = new Date(base + event.tick * 3000).toISOString();
    }
  }

  const trace: RestaurantArenaTraceV3 = {
    version: TRACE_V3_VERSION,
    episodeId: options.episodeId ?? game.state().episode.id,
    seed: game.state().seed,
    envVersion: options.envVersion ?? ARENA_ENV_VERSION,
    contractVersion: TRACE_V3_CONTRACT_VERSION,
    runKind: options.runKind,
    initialState: game.getInitialState(),
    events,
    deletion: {
      requestId: options.deletion?.requestId === undefined ? null : options.deletion.requestId,
      status: options.deletion?.status ?? "retained",
    },
    replay: game.getReplayRecord(),
    terminal: game.getTerminalStatus(),
  };
  if (options.sessionId !== undefined) trace.sessionId = options.sessionId;
  return trace;
}

/** Pretty-printed v3 JSON with decimal spelling for float fields. */
export function exportTraceJson(trace: RestaurantArenaTraceV3): string {
  return `${serializeJson(trace, true, false)}\n`;
}

/**
 * JSONL export: header object (everything except `events`) on line 0,
 * then one event per subsequent line.
 */
export function exportTraceJsonl(trace: RestaurantArenaTraceV3): string {
  const { events, ...header } = trace;
  return [JSON.stringify(header), ...events.map((event) => JSON.stringify(event)), ""].join("\n");
}

/** Reconstruct a trace from `exportTraceJson` or `exportTraceJsonl` text. */
export function parseArenaTrace(text: string): unknown {
  const trimmed = text.trim();
  if (!trimmed) throw new Error("trace file is empty");
  try {
    const parsed = JSON.parse(trimmed) as unknown;
    if (isRecord(parsed) && Array.isArray(parsed.events)) return parsed;
  } catch {
    // Multi-value JSONL cannot parse as a single JSON document.
  }
  const lines = trimmed.split(/\r?\n/).filter((line) => line.trim());
  if (lines.length === 0) throw new Error("trace file is empty");
  const header = JSON.parse(lines[0]!) as unknown;
  if (!isRecord(header)) throw new Error("JSONL header must be an object");
  const events = lines.slice(1).map((line) => JSON.parse(line) as unknown);
  return { ...header, events };
}

/**
 * Field-by-field validator for restaurant-arena-trace-v3. Collects every
 * problem rather than stopping at the first, so a malformed record is
 * rejected with a path for each bad field.
 */
export function validateArenaTraceV3(value: unknown): TraceValidationResult {
  const errors: TraceValidationError[] = [];
  const reject = (field: string, message: string) => {
    errors.push({ field, message });
  };

  if (!isRecord(value)) {
    reject("", "trace must be an object");
    return { valid: false, errors };
  }

  for (const key of extraKeys(value, ROOT_KEYS)) reject(key, "unexpected property");

  if (value.version !== TRACE_V3_VERSION) {
    reject("version", `expected "${TRACE_V3_VERSION}"`);
  }
  validateArenaId(value.episodeId, "episodeId", reject, true);
  if (value.sessionId !== undefined) validateArenaId(value.sessionId, "sessionId", reject, true);
  if (!Number.isInteger(value.seed) || (value.seed as number) < 0) {
    reject("seed", "expected a non-negative integer");
  }
  if (typeof value.envVersion !== "string" || value.envVersion.length < 1) {
    reject("envVersion", "expected a non-empty string");
  }
  if (value.contractVersion !== TRACE_V3_CONTRACT_VERSION) {
    reject("contractVersion", `expected "${TRACE_V3_CONTRACT_VERSION}"`);
  }
  if (typeof value.runKind !== "string" || !RUN_KINDS.has(value.runKind)) {
    reject("runKind", "expected live, synthetic, or benchmark");
  }

  validateInitialState(value.initialState, reject);
  if (!Array.isArray(value.events)) {
    reject("events", "expected an array");
  } else {
    value.events.forEach((event, index) => validateEvent(event, `events[${index}]`, reject));
  }
  validateDeletion(value.deletion, reject);
  validateReplay(value.replay, reject);
  validateTerminal(value.terminal, reject);

  return { valid: errors.length === 0, errors };
}

function validateArenaId(
  value: unknown,
  field: string,
  reject: (field: string, message: string) => void,
  required: boolean,
): void {
  if (value === undefined) {
    if (required) reject(field, "required");
    return;
  }
  if (typeof value !== "string" || value.length > 64 || !ARENA_ID_RE.test(value)) {
    reject(field, "expected an arena id");
  }
}

function validateSha256(
  value: unknown,
  field: string,
  reject: (field: string, message: string) => void,
): void {
  if (typeof value !== "string" || !SHA256_RE.test(value)) {
