getTerminalStatus(): { status: "active" | "completed" | "abandoned"; tick: number; reason: string | null } {
  return { status: this.isOver() ? "completed" : this.terminationReason ? "abandoned" : "active", tick: this.currentState.episode.tick, reason: this.isOver() ? "episode_complete" : this.terminationReason };
}

captureTrace(options: TraceCaptureOptions): RestaurantArenaTraceV3 {
  return captureArenaTrace(this, options);
}

/**
 * Native replay of a restaurant-arena-trace-v3 record back into a live
 * RestaurantGame. Overlay callers import this module directly.
 */

import {
  RestaurantGame,
  type ArenaInput,
  type ArenaInputRecord,
} from "./restaurant-game.js";
import { computeStateHash, type RestaurantArenaTraceV3 } from "./trace.js";

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Map the legacy expediter roster onto supply_lead so a historical trace
 * that still names that worker can be hashed against this engine's tick-0
 * state. Only role / worker id strings are rewritten.
 */
export function canonicalizeLegacyRoster(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalizeLegacyRoster);
  if (!isRecord(value)) return value;
  const mapped: Record<string, unknown> = {};
  for (const [key, child] of Object.entries(value)) {
    if (key === "role" || key === "id" || key === "actorId" || key === "workerId" || key === "to" || key === "targetRole") {
      if (child === "expediter") {
        mapped[key] = "supply_lead";
        continue;
      }
      if (child === "worker-expediter") {
        mapped[key] = "worker-supply_lead";
        continue;
      }
    }
    mapped[key] = canonicalizeLegacyRoster(child);
  }
  return mapped;
}

function rosterUsesExpediter(value: unknown): boolean {
  if (Array.isArray(value)) return value.some(rosterUsesExpediter);
  if (!isRecord(value)) {
    return value === "expediter" || value === "worker-expediter";
  }
  return Object.values(value).some(rosterUsesExpediter);
}

/** Map this engine's supply_lead roster back onto expediter for hash comparison. */
function mapSupplyLeadToExpediter(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(mapSupplyLeadToExpediter);
  if (!isRecord(value)) return value;
  const mapped: Record<string, unknown> = {};
  for (const [key, child] of Object.entries(value)) {
    if (key === "role" || key === "id" || key === "actorId" || key === "workerId" || key === "to" || key === "targetRole") {
      if (child === "supply_lead") {
        mapped[key] = "expediter";
        continue;
      }
      if (child === "worker-supply_lead") {
        mapped[key] = "worker-expediter";
        continue;
      }
    }
    mapped[key] = mapSupplyLeadToExpediter(child);
  }
  return mapped;
}

function hashForTrace(value: unknown, usesLegacyRoster: boolean): string {
  return computeStateHash(usesLegacyRoster ? mapSupplyLeadToExpediter(value) : value);
}

export function applyArenaReplayInput(
  game: RestaurantGame,
  input: ArenaInput | ArenaInputRecord,
  index?: number,
): void {
  switch (input.kind) {
    case "step":
      game.step(input.action);
      return;
    case "time":
      game.advanceTime();
      return;
    case "envelope":
      game.stepEnvelope(input.envelope, input.telemetry);
      return;
    case "controllers":
      game.setExternalControllers(input.roles);
      return;
    default: {
      const kind = (input as { kind?: unknown }).kind;
      throw new Error(`unknown replay input kind${index === undefined ? "" : ` at ${index}`}: ${String(kind)}`);
    }
  }
}

/**
 * Rebuild a live RestaurantGame from a captured v3 record.
 * Throws if the recorded tick-0 state, any checkpoint hash, the final state
 * hash, or any part of the terminal record disagrees with native replay.
 */
export function replayArenaTrace(trace: RestaurantArenaTraceV3): RestaurantGame {
  const game = new RestaurantGame(trace.seed, trace.replay.variation);
  const liveInitial = canonicalizeLegacyRoster(game.getInitialState());
  const recordedInitial = canonicalizeLegacyRoster(trace.initialState);
  if (computeStateHash(liveInitial) !== computeStateHash(recordedInitial)) {
    throw new Error("initial state mismatch");
  }

  const usesLegacyRoster = rosterUsesExpediter(trace.initialState) || rosterUsesExpediter(trace.replay.inputs);

  for (const [index, input] of trace.replay.inputs.entries()) {
    applyArenaReplayInput(game, input, index);
    const actual = hashForTrace(game.checkpointState(), usesLegacyRoster);
    if (actual !== input.stateHash) {
      throw new Error("checkpoint hash mismatch");
    }
    if (input.restaurantStateHash !== undefined) {
      const restaurantHash = hashForTrace(game.state(), usesLegacyRoster);
      if (restaurantHash !== input.restaurantStateHash) {
        throw new Error("checkpoint hash mismatch");
      }
    }
  }

  const finalHash = hashForTrace(game.checkpointState(), usesLegacyRoster);
  if (finalHash !== trace.replay.finalStateHash) {
    throw new Error("final state hash mismatch");
  }
  if (trace.replay.finalRestaurantStateHash !== undefined) {
    const restaurantHash = hashForTrace(game.state(), usesLegacyRoster);
    if (restaurantHash !== trace.replay.finalRestaurantStateHash) {
      throw new Error("final state hash mismatch");
    }
  }

  if (JSON.stringify(game.getTerminalStatus()) !== JSON.stringify(trace.terminal)) {
    throw new Error("terminal mismatch");
  }

  return game;
}

