      if (restaurantHash !== input.restaurantStateHash) {
        throw new Error("checkpoint hash mismatch");
      }
    }
  }

  const finalHash = hashForTrace(game.checkpointState(), usesLegacyRoster);
  if (finalHash !== trace.replay.finalStateHash) {
    throw new Error("final state hash mismatch");
  }
  if (trace.replay.finalRestaurantStateHash !== undefined) {
    const restaurantHash = hashForTrace(game.state(), usesLegacyRoster);
    if (restaurantHash !== trace.replay.finalRestaurantStateHash) {
      throw new Error("final state hash mismatch");
    }
  }

  if (JSON.stringify(game.getTerminalStatus()) !== JSON.stringify(trace.terminal)) {
    throw new Error("terminal mismatch");
  }

  return game;
}
