import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { RestaurantGame } from "../src/games/restaurant-arena/restaurant-game.js";
import {
  canonicalJson,
  captureArenaTrace,
  exportTraceJson,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

const FIXTURE_PATH = resolve("contracts/fixtures/restaurant-arena-trace-v3.json");
const BENCHMARK_SEED = 218220;
const BENCHMARK_VARIATION = "dinner-rush";
const BENCHMARK_EPISODE_ID = "dinner-rush-benchmark-218220";
const BENCHMARK_START_TIME = "2026-09-05T18:00:00.000Z";

/** Play the frozen dinner-rush sequence the v3 fixture records. */
export function playBenchmarkShift(seed = BENCHMARK_SEED): RestaurantGame {
  const game = new RestaurantGame(seed, BENCHMARK_VARIATION);
  game.step("sim_start");
  for (let i = 0; i < 10; i++) game.step("tick");
  game.step("verify_substitution");
  for (let i = 0; i < 14; i++) game.step("tick");
  return game;
}

export function captureBenchmarkTrace(): RestaurantArenaTraceV3 {
  return captureArenaTrace(playBenchmarkShift(), {
    runKind: "benchmark",
    episodeId: BENCHMARK_EPISODE_ID,
    startTime: BENCHMARK_START_TIME,
  });
}

function tracesMatch(left: string, right: string): boolean {
  return canonicalJson(JSON.parse(left)) === canonicalJson(JSON.parse(right));
}

function main(): void {
  const check = process.argv.includes("--check");
  const trace = captureBenchmarkTrace();
  const json = exportTraceJson(trace);

  if (check) {
    let onDisk: string;
    try {
      onDisk = readFileSync(FIXTURE_PATH, "utf8");
    } catch {
      console.error(`Fixture missing: ${FIXTURE_PATH}`);
      process.exit(1);
      return;
    }
    if (!tracesMatch(json, onDisk)) {
      console.error(`Fixture is stale: ${FIXTURE_PATH}`);
      process.exit(1);
    }
    console.log("Fixture is current");
    return;
  }

  mkdirSync(dirname(FIXTURE_PATH), { recursive: true });
  writeFileSync(FIXTURE_PATH, json);
  console.log(`Wrote ${FIXTURE_PATH}`);
}

main();

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { replayArenaTrace } from "../src/games/restaurant-arena/replay.js";
import {
  parseArenaTrace,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
} from "../src/games/restaurant-arena/trace.js";

function usage(): never {
  console.error("Usage: bun scripts/replay-arena-trace.ts <path-to-trace.json-or-.jsonl>");
  process.exit(2);
}

function main(): void {
  const pathArg = process.argv[2];
  if (!pathArg || pathArg.startsWith("-")) usage();

  try {
    const text = readFileSync(resolve(pathArg), "utf8");
    const parsed = parseArenaTrace(text);
    const validation = validateArenaTraceV3(parsed);
    if (!validation.valid) {
      for (const error of validation.errors) {
        console.error(`${error.field}: ${error.message}`);
      }
      process.exit(1);
    }
    replayArenaTrace(parsed as RestaurantArenaTraceV3);
    console.log("Native replay passed");
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(message);
    process.exit(1);
  }
}

main();

