import { describe, expect, it } from "bun:test";
import { RestaurantGame } from "./restaurant-game.js";
import { replayArenaTrace } from "./replay.js";
import {
  captureArenaTrace,
  exportTraceJson,
  exportTraceJsonl,
  parseArenaTrace,
  validateArenaTraceV3,
  type RestaurantArenaTraceV3,
  type TraceV3Event,
} from "./trace.js";

function playShortShift(): RestaurantGame {
  const game = new RestaurantGame(218220);
  game.step("sim_start");
  for (let i = 0; i < 24; i++) game.step("tick");
  return game;
}

describe("restaurant-arena-trace-v3 capture", () => {
  it("captures a schema-valid record from a running game", () => {
    const game = playShortShift();
    const viaHelper = captureArenaTrace(game, { runKind: "live" });
    const viaMethod = game.captureTrace({ runKind: "live" });
    expect(viaMethod.version).toBe("restaurant-arena-trace/v3");
    expect(viaMethod.runKind).toBe("live");
    expect(viaMethod.terminal).toEqual(game.getTerminalStatus());
    expect(viaMethod.initialState).toEqual(game.getInitialState());
    expect(viaMethod.replay.inputs.length).toBeGreaterThan(0);
    expect(viaHelper.replay.finalStateHash).toBe(viaMethod.replay.finalStateHash);
    const validation = validateArenaTraceV3(viaMethod);
    expect(validation.valid).toBe(true);
    expect(validation.errors).toEqual([]);
  });

  it("requires runKind so live, synthetic and benchmark stay distinguishable", () => {
    const game = new RestaurantGame(218220);
    expect(() => captureArenaTrace(game, {} as never)).toThrow(/runKind/);
    expect(game.captureTrace({ runKind: "synthetic" }).runKind).toBe("synthetic");
    expect(game.captureTrace({ runKind: "benchmark" }).runKind).toBe("benchmark");
  });

  it("stamps additionalEvents with the round their tick falls in", () => {
    const game = new RestaurantGame(218220);
    game.step("sim_start");
    const note: TraceV3Event = {
      tick: 8,
      kind: "message",
      timestamp: "2026-09-05T18:00:24.000Z",
      stateHash: "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      text: "out-of-band player note",
    };
    const trace = game.captureTrace({ runKind: "live", additionalEvents: [note] });
    const merged = trace.events.find((event) => event.text === "out-of-band player note");
    expect(merged?.round).toBe(4);
    expect(trace.events.some((event) => event.tick === 0)).toBe(true);
  });

  it("replaces the journal wholesale when events is passed", () => {
    const game = new RestaurantGame(218220);
    const replacement: TraceV3Event[] = [
      {
        tick: 0,
        kind: "observation",
        timestamp: "2026-09-05T18:00:00.000Z",
        stateHash: "sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
        text: "replacement journal",
      },
    ];
    const trace = captureArenaTrace(game, { runKind: "synthetic", events: replacement });
    expect(trace.events).toHaveLength(1);
    expect(trace.events[0]?.text).toBe("replacement journal");
  });

  it("identifying the session a trace came from (#281)", () => {
    const game = new RestaurantGame(218220);
    const first = game.captureTrace({ runKind: "live", sessionId: "session-alpha" });
    const second = game.captureTrace({ runKind: "live", sessionId: "session-beta" });
    expect(first.episodeId).toBe(second.episodeId);
    expect(first.sessionId).toBe("session-alpha");
    expect(second.sessionId).toBe("session-beta");
    expect(first.sessionId).not.toBe(second.sessionId);

    const missing = game.captureTrace({ runKind: "live" });
    expect(missing.sessionId).toBeUndefined();
    expect(validateArenaTraceV3(missing).valid).toBe(true);

    const malformed = { ...first, sessionId: "not a session" };
    const validation = validateArenaTraceV3(malformed);
    expect(validation.valid).toBe(false);
    expect(validation.errors.some((error) => error.field === "sessionId")).toBe(true);
  });
});

describe("restaurant-arena-trace-v3 export and validation", () => {
  it("exports JSON and JSONL that round-trip through parse and validate", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const json = exportTraceJson(trace);
    const jsonl = exportTraceJsonl(trace);
    expect(validateArenaTraceV3(JSON.parse(json)).valid).toBe(true);
    expect(validateArenaTraceV3(parseArenaTrace(jsonl)).valid).toBe(true);
    const lines = jsonl.trim().split("\n");
    expect(lines.length).toBe(trace.events.length + 1);
    expect(JSON.parse(lines[0]!)).toMatchObject({ version: trace.version, replay: trace.replay });
  });

  it("rejects malformed records field by field", () => {
    const trace = new RestaurantGame(218220).captureTrace({ runKind: "live" });
    const broken = {
      ...trace,
      version: "nope",
      runKind: "demo",
      seed: -1,
      terminal: { ...trace.terminal, status: "won", reason: 12 },
      replay: { ...trace.replay, variation: "brunch", finalStateHash: "not-a-hash" },
    };
    const validation = validateArenaTraceV3(broken);
    expect(validation.valid).toBe(false);
    const fields = validation.errors.map((error) => error.field);
    expect(fields).toContain("version");
    expect(fields).toContain("runKind");
    expect(fields).toContain("seed");
    expect(fields).toContain("terminal.status");
    expect(fields).toContain("terminal.reason");
    expect(fields).toContain("replay.variation");
    expect(fields).toContain("replay.finalStateHash");
  });
});

describe("native replayArenaTrace", () => {
  it("rebuilds the live game and matches the recorded terminal", () => {
    const original = playShortShift();
    const trace = original.captureTrace({ runKind: "live" });
    const replayed = replayArenaTrace(trace);
    expect(replayed).toBeInstanceOf(RestaurantGame);
    expect(replayed.getTerminalStatus()).toEqual(original.getTerminalStatus());
    expect(replayed.checkpointState()).toEqual(original.checkpointState());
  });

  it("throws when any part of the terminal record disagrees", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const reasonTampered: RestaurantArenaTraceV3 = {
      ...trace,
      terminal: { ...trace.terminal, reason: "tampered" },
    };
    expect(() => replayArenaTrace(reasonTampered)).toThrow("terminal mismatch");
    const tickTampered: RestaurantArenaTraceV3 = {
      ...trace,
      terminal: { ...trace.terminal, tick: trace.terminal.tick + 1 },
    };
    expect(() => replayArenaTrace(tickTampered)).toThrow("terminal mismatch");
  });

  it("throws when initialState is altered even if every field still parses", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const outcomes = (trace.initialState as { outcomes: { cash: number } }).outcomes;
    const tampered: RestaurantArenaTraceV3 = {
      ...trace,
      initialState: {
        ...trace.initialState,
        outcomes: { ...outcomes, cash: outcomes.cash + 1 },
      },
    };
    expect(validateArenaTraceV3(tampered).valid).toBe(true);
    expect(() => replayArenaTrace(tampered)).toThrow("initial state mismatch");
  });

  it("replays a record that still names the legacy expediter worker", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const initial = structuredClone(trace.initialState) as {
      workers: Array<{ id: string; role: string }>;
    };
    for (const worker of initial.workers) {
      if (worker.role === "supply_lead") {
        worker.role = "expediter";
        worker.id = "worker-expediter";
      }
    }
    const legacy: RestaurantArenaTraceV3 = { ...trace, initialState: initial };
    const replayed = replayArenaTrace(legacy);
    expect(replayed.getTerminalStatus()).toEqual(trace.terminal);
  });

  it("throws when a checkpoint hash disagrees", () => {
    const trace = playShortShift().captureTrace({ runKind: "live" });
    const inputs = trace.replay.inputs.map((input, index) =>
      index === 0 ? { ...input, stateHash: "sha256:" + "ab".repeat(32) } : input,
    );
    const tampered: RestaurantArenaTraceV3 = {
      ...trace,
      replay: { ...trace.replay, inputs },
    };
    expect(() => replayArenaTrace(tampered)).toThrow("checkpoint hash mismatch");
  });
});

